<script>
    document.addEventListener('DOMContentLoaded', function() {
        const priceSection = document.querySelector('.productView-price');
        
        if (!priceSection) return;

        let observer = null;

        function updateSavePrice() {
            const oldPriceElem = priceSection.querySelector('span[data-product-non-sale-price-without-tax]');
            const mainPriceElem = priceSection.querySelector('span[data-product-price-without-tax]');
            
            const savingContainer = priceSection.querySelector('.price-section--saving, .price.section.saving.price');
            const savedValueElem = priceSection.querySelector('span[data-product-price-saved]');

            if (oldPriceElem && mainPriceElem) {
                const oldText = oldPriceElem.innerText.trim();
                const mainText = mainPriceElem.innerText.trim();

                if (oldText !== '' && mainText !== '') {
                    const oldVal = parseFloat(oldText.replace(/[^0-9.-]+/g,""));
                    const mainVal = parseFloat(mainText.replace(/[^0-9.-]+/g,""));

                    if (!isNaN(oldVal) && !isNaN(mainVal) && oldVal > mainVal) {
                        const saveAmount = (oldVal - mainVal).toFixed(2);
                        const expectedText = 'Save $' + saveAmount;

                        if (observer) observer.disconnect();

                        // Set the value inside saved span explicitly
                        if (savedValueElem && savedValueElem.innerText !== expectedText) {
                            savedValueElem.innerText = expectedText;
                        }

                        if (savingContainer) {
                            // Target ONLY the bracket/label spans around it and clear them
                            const sideSpans = savingContainer.querySelectorAll('span.price');
                            sideSpans.forEach(span => {
                                if (span !== savedValueElem) {
                                    span.innerText = '';
                                }
                            });
                            
                            savingContainer.style.setProperty('display', 'block', 'important');
                        }

                        if (observer) observer.observe(priceSection, { childList: true, subtree: true, characterData: true });

                    } else {
                        if (observer) observer.disconnect();
                        if (savingContainer) {
                            savingContainer.style.setProperty('display', 'none', 'important');
                        }
                        if (observer) observer.observe(priceSection, { childList: true, subtree: true, characterData: true });
                    }
                }
            }
        }

        observer = new MutationObserver(function() {
            updateSavePrice();
        });

        observer.observe(priceSection, {
            childList: true,
            subtree: true,
            characterData: true
        });

        updateSavePrice();
    });
</script>

<script>
document.addEventListener("DOMContentLoaded", function() {
    const maxVisibleSwatches = 9;
    
    const swatchContainer = document.querySelector('.productView-options [data-product-attribute="swatch"] .form-field-control, .productView-options [data-product-attribute="swatch"]');
    
    if (swatchContainer) {
        const swatches = swatchContainer.querySelectorAll('.form-option-wrapper');
        
        if (swatches.length > maxVisibleSwatches) {
            let hiddenCount = swatches.length - maxVisibleSwatches;
            
            swatches.forEach((swatch, index) => {
                if (index >= maxVisibleSwatches) {
                    swatch.classList.add('swatch-hidden');
                }
            });
            
            const plusBox = document.createElement('div');
            plusBox.className = 'swatch-more-toggle';
            plusBox.innerHTML = `+${hiddenCount}`;
            
            swatches[maxVisibleSwatches - 1].parentNode.insertBefore(plusBox, swatches[maxVisibleSwatches].nextSibling);
            
            plusBox.addEventListener('click', function() {
                swatches.forEach(swatch => {
                    swatch.classList.remove('swatch-hidden');
                });
                plusBox.style.display = 'none'; 
            });
        }
    }
});
</script>

<script>
(function($) {
    function calculateFinalPricing() {
        // --- 1. SQFT & LINEAR FT Data Detection ---
        let rawSqftData = "";
        let isLinearFt = false;
        let hasPackIncludesField = false; 
        
        $('.productView-info-name').each(function() {
            let name = $(this).text().trim().toLowerCase();
            
            if (name.indexOf('pack includes') !== -1 || name.indexOf('pack_includes') !== -1) {
                hasPackIncludesField = true;
            }

            if (name.indexOf('sq_ft_data') !== -1 || name.indexOf('sq_ft_per_pack') !== -1) {
                rawSqftData = $(this).next('.productView-info-value').text().trim();
                //$(this).closest('.single-infoValue').hide(); 
                this.closest('.single-infoValue').style.setProperty('display', 'none', 'important');
            }
            
            if (name.indexOf('linear_ft_data') !== -1 || name.indexOf('linear_ft_per_pack') !== -1 || name.indexOf('linear_foot') !== -1) {
                rawSqftData = $(this).next('.productView-info-value').text().trim();
                isLinearFt = true;
                //$(this).closest('.single-infoValue').hide();
                this.closest('.single-infoValue').style.setProperty('display', 'none', 'important');
            }
        });

        if (!rawSqftData) {
            $('#custom-pricing-logic').hide();
            return; 
        }

        let productTitle = $('.productView-title').text().toLowerCase() || "";
        let breadcrumbsText = $('.breadcrumbs').text().toLowerCase() || "";
        let urlPathText = window.location.pathname.toLowerCase() || "";
        let globalSearchScope = breadcrumbsText + " | " + urlPathText + " | " + productTitle;

        if (globalSearchScope.indexOf('molding') !== -1 || globalSearchScope.indexOf('moulding') !== -1) {
            isLinearFt = true;
        }

        let isAccessory = (rawSqftData.toLowerCase() === 'clip' || globalSearchScope.indexOf('clip') !== -1);

        // --- 2. Option Tracking Configuration ---
        function checkContainerSelected($container) {
            if ($container.length === 0) return false;
            if ($container.find('input:checked').length > 0) return true;
            
            let selectVal = $container.find('select').val();
            if (selectVal !== "" && selectVal !== undefined && selectVal !== null) {
                let $selectedOption = $container.find('select option:selected');
                if (!$selectedOption.is(':disabled') && selectVal.toLowerCase().indexOf('choose') === -1) {
                    return true;
                }
            }
            return false;
        }

        function getExactFormContainer(labelText) {
            return $('.form-field').filter(function() {
                let labelStr = $(this).find('.form-label').text().trim().toLowerCase() || "";
                return labelStr.indexOf(labelText.toLowerCase()) !== -1 && !labelStr.includes('acoustical');
            });
        }

        let colorContainer = getExactFormContainer("Color");
        let packContainer = getExactFormContainer("Pack");
        let sizeContainer = getExactFormContainer("Size");
        let settingContainer = getExactFormContainer("Setting");
        let finishContainer = getExactFormContainer("Finish");
        let materialContainer = getExactFormContainer("Material"); 
        let substrateContainer = getExactFormContainer("Substrate");
        let installationContainer = $('.form-field').filter(function() {
            let labelStr = $(this).find('.form-label').text().trim().toLowerCase() || "";
            return labelStr.indexOf('installation') !== -1;
        });

        let hasColorOption = colorContainer.length > 0;
        let hasPackOption = packContainer.length > 0;
        let hasSizeOption = sizeContainer.length > 0;
        let hasSettingOption = settingContainer.length > 0;
        let hasFinishOption = finishContainer.length > 0;
        let hasMaterialOption = materialContainer.length > 0;
        let hasSubstrateOption = substrateContainer.length > 0;
        let hasInstallationOption = installationContainer.length > 0;

        let colorSelected = checkContainerSelected(colorContainer);
        let packSelected = checkContainerSelected(packContainer);
        let sizeSelected = checkContainerSelected(sizeContainer);
        let settingSelected = checkContainerSelected(settingContainer);
        let finishSelected = checkContainerSelected(finishContainer);
        let materialSelected = checkContainerSelected(materialContainer);
        let substrateSelected = checkContainerSelected(substrateContainer);
        let installationSelected = checkContainerSelected(installationContainer);

        function normalizeKeyText(str) {
            let base = str.toLowerCase();
            if (base.includes('(') && base.includes(')')) {
                let matches = base.match(/\(([^)]+)\)/);
                if (matches && matches[1]) {
                    base = matches[1]; 
                }
            }
            return base.replace(/-/g, ' ') 
                       .replace(/[^a-z0-9\/x\s]/g, '') 
                       .replace(/\s+/g, ' ')
                       .replace(/\s*x\s*/g, 'x') 
                       .trim();
        }

        let currentSelections = [];
        let isSampleSelected = false;

        $('input[name^="attribute"]:checked').each(function() {
            let text = $(this).next().text().trim().toLowerCase();
            if (text.includes('yes') || text.includes('nrc')) return;
            if (text.includes('sample')) isSampleSelected = true;
            let cleanKey = normalizeKeyText(text);
            currentSelections.push({
                full: cleanKey,
                numbers: text.replace(/[^0-9.]/g, '')
            });
        });

        $('select[name^="attribute"]').each(function() {
            let $selectedOption = $(this).find('option:selected');
            let selectValue = $(this).val();
            if (selectValue && selectValue !== "") {
                let selectedOptionText = $selectedOption.text().trim().toLowerCase();
                if (selectedOptionText.includes('sample')) isSampleSelected = true;
                let cleanKey = normalizeKeyText(selectedOptionText);
                currentSelections.push({
                    full: cleanKey,
                    numbers: selectedOptionText.replace(/[^0-9.]/g, '')
                });
            }
        });

        let packText = "";
        if (packSelected) {
            let selectedPackInput = packContainer.find('input:checked');
            if (selectedPackInput.length > 0) {
                let radioLabel = selectedPackInput.next('label').text().trim();
                let swatchText = selectedPackInput.next('.form-option').find('.form-option-variant').text().trim();
                let defaultText = selectedPackInput.next('.form-option').text().trim();
                packText = (radioLabel || swatchText || defaultText).toLowerCase();
            } else {
                packText = packContainer.find('select option:selected').text().trim().toLowerCase();
            }
        }

        // --- 3. Price Capture Engine ---
        let priceElem = $('.price-section--withoutTax').not('.rrp-price--withoutTax, .non-sale-price--withoutTax').first();
        let nowPriceRaw = priceElem.text().trim();
        if (!nowPriceRaw) return;

        // --- 4. Visibility Validation Engine ---
        let shouldShow = true;
        if (hasColorOption && !colorSelected) shouldShow = false;
        if (hasPackOption && !packSelected) shouldShow = false;
        if (hasSizeOption && !sizeSelected) shouldShow = false;
        if (hasSettingOption && !settingSelected) shouldShow = false; 
        if (hasFinishOption && !finishSelected) shouldShow = false;   
        if (hasMaterialOption && !materialSelected) shouldShow = false; 
        if (hasSubstrateOption && !substrateSelected) shouldShow = false;
        if (hasInstallationOption && !installationSelected) shouldShow = false;

        if (isSampleSelected || packText.includes('sample')) {
            shouldShow = false;
        }

        let addToCartBtn = $('#form-action-addToCart');
        let isCartDisabled = addToCartBtn.prop('disabled') || addToCartBtn.is(':disabled') || addToCartBtn.hasClass('disabled');
        let btnText = addToCartBtn.val() || addToCartBtn.text() || "";
        let isUnavailableText = btnText.toLowerCase().indexOf('unavailable') !== -1 || btnText.toLowerCase().indexOf('out of stock') !== -1;

        if (isCartDisabled || isUnavailableText) {
            shouldShow = false;
        }

        if (!shouldShow) {
            $('#custom-pricing-logic').hide();
            return;
        }

        // --- 5. Price & Mapping Logic ---
        let nowPrice = parseFloat(nowPriceRaw.replace(/[^0-9.-]+/g, "")) || 0;
        if (nowPrice <= 0) {
            $('#custom-pricing-logic').hide();
            return;
        }

        // --- 6. UI Rendering Engine ---
        if (isAccessory) {
            let itemsCount = 0;
            for (let selection of currentSelections) {
                let parsedNum = parseInt(selection.numbers);
                if (!isNaN(parsedNum) && parsedNum > 1) {
                    itemsCount = parsedNum; 
                    break;
                }
            }

            if (itemsCount === 0) {
                let titleNumbers = productTitle.replace(/[^0-9]/g, '');
                itemsCount = parseInt(titleNumbers) || 25; 
            }

            let totalPanels = Math.floor(itemsCount / 3); 
            let pricePerClip = (nowPrice / itemsCount).toFixed(2);
            
            $('#display-total-sqft').text(`Covers ${totalPanels} Panels`);
            $('#display-price-per-ft').text(`$${pricePerClip} Per Clip`);

        } else {
            let totalCoverage = 0;
            if (rawSqftData.includes('|')) {
                let dataMap = {};
                let isNumericMap = true; 
                rawSqftData.split('|').forEach(item => {
                    let parts = item.split(':');
                    if (parts.length === 2) {
                        let mapKey = normalizeKeyText(parts[0]);
                        dataMap[mapKey] = parseFloat(parts[1]);
                        if (/[a-z]/i.test(mapKey)) {
                            isNumericMap = false;
                        }
                    }
                });

                for (let selection of currentSelections) {
                    if (dataMap[selection.full]) {
                        totalCoverage = dataMap[selection.full];
                        break;
                    } 
                    if (selection.numbers && dataMap[selection.numbers]) {
                        totalCoverage = dataMap[selection.numbers];
                        break;
                    }
                }

                if (!totalCoverage) {
                    for (let selection of currentSelections) {
                        if (isNumericMap && !selection.numbers) {
                            continue; 
                        }

                        let found = false;
                        for (let key in dataMap) {
                            if (selection.full !== "" && (selection.full.includes(key) || key.includes(selection.full))) {
                                totalCoverage = dataMap[key];
                                found = true;
                                break;
                            }
                        }
                        if (found) break;
                    }
                }
            } else {
                totalCoverage = parseFloat(rawSqftData) || 0;
            }

            if (!totalCoverage || totalCoverage <= 0) { 
                $('#custom-pricing-logic').hide(); 
                return; 
            }

            let finalUnitLabel = "Piece"; 
            let selectionTextsCombined = "";
            
            $('input[name^="attribute"]:checked').each(function() {
                selectionTextsCombined += " " + $(this).next().text().trim().toLowerCase();
            });
            $('select[name^="attribute"] option:selected').each(function() {
                selectionTextsCombined += " " + $(this).text().trim().toLowerCase();
            });

            let completeSearchString = globalSearchScope + " " + selectionTextsCombined;
            let hasRollWord = /\brolls?\b/i.test(completeSearchString);
            
            if (hasPackIncludesField) {
                finalUnitLabel = "Pack"; 
            } else if (completeSearchString.indexOf('kit') !== -1) {
                finalUnitLabel = "Kit"; 
            } else if (completeSearchString.indexOf('pack') !== -1) {
                finalUnitLabel = "Pack";
            } else if (hasPackOption && packSelected && !packText.includes('single') && !packText.includes('1 pack')) {
                finalUnitLabel = "Pack";
            } else {
                if (hasRollWord) {
                    finalUnitLabel = "Roll";
                } else if (globalSearchScope.indexOf('molding') !== -1 || globalSearchScope.indexOf('moulding') !== -1) {
                    finalUnitLabel = "Molding";
                } else if (globalSearchScope.indexOf('panel') !== -1) {
                    finalUnitLabel = "Panel";
                } else if (globalSearchScope.indexOf('skin') !== -1) {
                    finalUnitLabel = "Skin";
                } else if (globalSearchScope.indexOf('beam') !== -1) {
                    finalUnitLabel = "Beam";
                } else if (globalSearchScope.indexOf('plank') !== -1) {
                    finalUnitLabel = "Plank";
                } else if (globalSearchScope.indexOf('tile') !== -1) {
                    finalUnitLabel = "Tile";
                } else {
                    finalUnitLabel = "Piece"; 
                }
            }

            let nowPerUnitFt = (nowPrice / totalCoverage).toFixed(2);
            let displayUnit = finalUnitLabel.charAt(0).toUpperCase() + finalUnitLabel.slice(1);
            let dynamicFtSuffix = isLinearFt ? "ln.ft." : "Sq.Ft";
            
            $('#display-price-per-ft').text(`$${nowPerUnitFt} per ${dynamicFtSuffix}`);
            $('#display-total-sqft').text(`| ${totalCoverage} ${dynamicFtSuffix} Per ${displayUnit}`);
        }

        // DOM Positioning logic
       /* priceElem.css({'display': 'flex', 'align-items': 'center', 'flex-wrap': 'wrap'});
            if ($("#custom-pricing-logic").parent()[0] !== priceElem[0]) {
                $("#custom-pricing-logic").appendTo(priceElem);
            }*/
        $('#custom-pricing-logic').show().css('display', 'flex');
    }

    $(document).ready(function() {
        /*if ($('#custom-pricing-logic').length === 0) {
                $('.price-section--withoutTax').first().append('<div id="custom-pricing-logic" style="display:none; font-size:16px; margin-left:15px; font-weight:bold; color: #333;"></div>');
        }*/

        setTimeout(calculateFinalPricing, 600);
        setTimeout(calculateFinalPricing, 1500); 

        const priceTarget = document.querySelector('.productView-price'); 
        if (priceTarget) {
            const observer = new MutationObserver(() => setTimeout(calculateFinalPricing, 300));
            observer.observe(priceTarget, { childList: true, characterData: true, subtree: true });
        }

        $(document).on('change click', 'input[name^="attribute"]', function() {
            setTimeout(calculateFinalPricing, 400);
        });

        $(document).on('change', 'select[name^="attribute"]', function() {
            setTimeout(calculateFinalPricing, 400);
        });
    });
})(jQuery);

