<script>
    document.addEventListener('DOMContentLoaded', function() {
        const priceSections = document.querySelectorAll('.price-section, .productView-price');
        
        priceSections.forEach(section => {
            function removeLabels(node) {
                node.childNodes.forEach(child => {
                    if (child.nodeType === Node.TEXT_NODE) {
                        child.nodeValue = child.nodeValue
                            .replace(/Was:/gi, '')
                            .replace(/Now:/gi, '')
                            .replace(/From:/gi, '');
                    } else if (child.nodeType === Node.ELEMENT_NODE) {
                        removeLabels(child);
                    }
                });
            }
            removeLabels(section);
        });
    });
</script>

<!-- Simple Script to Handle Popup Injection -->
<script>
function openVideoModal(videoId) {
    // Remove existing lightbox if any
    const existingOverlay = document.getElementById('custom-video-lightbox');
    if (existingOverlay) {
        existingOverlay.remove();
    }

    // Create a clean overlay popup dynamically
    const overlay = document.createElement('div');
    overlay.id = 'custom-video-lightbox';
    overlay.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); z-index: 999999; display: flex; align-items: center; justify-content: center;';
    
    overlay.innerHTML = `
        <div style="position: relative; width: 80%; max-width: 800px; aspect-ratio: 16/9; background: #000;">
            <iframe src="https://www.youtube.com/embed/${videoId}?autoplay=1" style="width: 100%; height: 100%; border: 0;" allowfullscreen></iframe>
            <button onclick="document.getElementById('custom-video-lightbox').remove()" style="position: absolute; top: -40px; right: 0; background: #fff; border: none; font-size: 20px; font-weight: bold; padding: 5px 10px; cursor: pointer; border-radius: 3px;">&times; Close</button>
        </div>
    `;
    
    document.body.appendChild(overlay);
    
    // Close on clicking outside the video box
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) {
            overlay.remove();
        }
    });
}
</script>


