<script>
 $(document).ready(function() {
    // Auto-detect and show relevant calculator based on product category
    var categoriesText = $('#product-category-list').attr('data-categories') || '';
    
    $('.category-calc-box').each(function() {
        var allowedCats = $(this).attr('data-cat').split(',');
        var showThisBox = false;
        
        for (var i = 0; i < allowedCats.length; i++) {
            if (categoriesText.indexOf(allowedCats[i].trim()) !== -1) {
                showThisBox = true;
                break;
            }
        }
        
        if (showThisBox) {
            $(this).show();
        }
    });

    // Open Main Calculator Popup
    $('#trigger-calculator').on('click', function(e) {
        e.preventDefault();
        $('#project-calculator-modal').css('display', 'flex');
    });

    // Close Popup
    $('.calculator-close-btn').on('click', function() {
        $('#project-calculator-modal').hide();
    });

    // Close when clicking outside content
    $('#project-calculator-modal').on('click', function(e) {
        if ($(e.target).is('#project-calculator-modal')) {
            $(this).hide();
        }
    });

    // Individual Accordion/Slide toggles
    $('.slide_open').on('click', function() { $('#slide').slideToggle(); });
    $('.slide1_open').on('click', function() { $('#slide1').slideToggle(); });
    $('.slide2_open').on('click', function() { $('#slide2').slideToggle(); });
    $('.slide3_open').on('click', function() { $('#slide3').slideToggle(); });

    // Calculations logic
    $('#calc_ceiling_btn').on('click', function(e) {
        e.preventDefault();
        var l = parseFloat($('#ceiling_length').val()) || 0;
        var w = parseFloat($('#ceiling_width').val()) || 0;
        if(l > 0 && w > 0) {
            var sqft = l * w;
            var total = Math.ceil((sqft * 1.1) / 2.69);
            $('#ceiling_result').html('<span style="color:green;">Required: ' + total + ' Tiles (' + sqft.toFixed(2) + ' sq.ft with 10% waste)</span>');
        } else {
            $('#ceiling_result').html('<span style="color:red;">Enter valid numbers</span>');
        }
    });

    $('#calc_molding_btn').on('click', function(e) {
        e.preventDefault();
        var lf = parseFloat($('#molding_linear_feet').val()) || 0;
        if(lf > 0) {
            var total = Math.ceil((lf * 1.1) / 6.5);
            $('#molding_result').html('<span style="color:green;">Required: ' + total + ' pieces</span>');
        } else {
            $('#molding_result').html('<span style="color:red;">Enter valid length</span>');
        }
    });

    $('#calc_panel_btn').on('click', function(e) {
        e.preventDefault();
        var h = parseFloat($('#panel_height').val()) || 0;
        var w = parseFloat($('#panel_width').val()) || 0;
        if(h > 0 && w > 0) {
            var sqft = h * w;
            var total = Math.ceil((sqft * 1.1) / 2.0);
            $('#panel_result').html('<span style="color:green;">Required: ' + total + ' Panels</span>');
        } else {
            $('#panel_result').html('<span style="color:red;">Enter valid dimensions</span>');
        }
    });

    $('#calc_foam_btn').on('click', function(e) {
        e.preventDefault();
        var l = parseFloat($('#foam_length').val()) || 0;
        var w = parseFloat($('#foam_width').val()) || 0;
        if(l > 0 && w > 0) {
            var sqft = l * w;
            var total = Math.ceil((sqft * 1.1) / 1.0);
            $('#foam_result').html('<span style="color:green;">Required: ' + total + ' Planks</span>');
        } else {
            $('#foam_result').html('<span style="color:red;">Enter valid measurements</span>');
        }
    });
});
</script>

